// Generated by forge. The types engine for TypeScript (SPECS §15): a daemon that keeps
// TypeScript 7's language server (tsc --lsp) running for one repository and answers
// the hooks' type questions through a FIFO. Started by forge_types_up as
//   bun types_typescript.mjs <root> <state-dir> <typescript version>
// It detaches (its own session), then writes "ready <server> <version>" (or
// "failed <reason>") to the FIFO <state-dir>/started. The protocol on <state-dir>/in is
// the Python engine's (types_python.py): "changed<TAB><path>", "stop", "restart", or
// the absolute path of a question directory (req: ast-grep matches; reply: the matches
// whose forge_where holds, "error<TAB>..." lines, "end"). Node-compatible: no Bun-only API.
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = fs.realpathSync(process.argv[2]);
const STATE = process.argv[3];
const VERSION = process.argv[4];
const IDLE = Number(process.env.FORGE_TYPES_IDLE ?? 1800) * 1000;
const logFile = fs.openSync(path.join(STATE, "log"), "a");
const log = (...a) => fs.writeSync(logFile, `${new Date().toISOString().slice(11, 19)} ${a.join(" ")}\n`);

const uri = (p) => pathToFileURL(fs.existsSync(p) ? fs.realpathSync(p) : p).href;
const pathOf = (u) => (u.startsWith("file://") ? fileURLToPath(u) : u);

/** The LSP position (UTF-16 columns, as JS strings count) of a string index. */
function position(text, index) {
  let line = 0;
  for (let i = text.indexOf("\n"); i >= 0 && i < index; i = text.indexOf("\n", i + 1)) line++;
  return { line, character: index - (text.lastIndexOf("\n", index - 1) + 1) };
}
function indexOf(text, pos) {
  let i = 0;
  for (let l = 0; l < pos.line; l++) i = text.indexOf("\n", i) + 1;
  return i + pos.character;
}

// ---------------------------------------------------------------- the language server

class Server {
  constructor() {
    // tsc's bin starts the native compiler; --bun: no Node needed
    this.proc = spawn(process.execPath, ["x", "--bun", "-p", `typescript@${VERSION}`, "tsc", "--lsp", "--stdio"], { cwd: ROOT, stdio: ["pipe", "pipe", logFile] });
    this.proc.on("exit", () => {
      log("server exited");
      process.exit(3);
    });
    this.buf = Buffer.alloc(0);
    this.next = 0;
    this.waiting = new Map();
    this.versions = new Map();
    this.texts = new Map();
    this.proc.stdout.on("data", (d) => this.read(d));
  }
  read(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const sep = this.buf.indexOf("\r\n\r\n");
      if (sep < 0) return;
      const len = Number(/content-length: *(\d+)/i.exec(this.buf.subarray(0, sep).toString())[1]);
      if (this.buf.length < sep + 4 + len) return;
      const msg = JSON.parse(this.buf.subarray(sep + 4, sep + 4 + len).toString());
      this.buf = this.buf.subarray(sep + 4 + len);
      if (msg.method && msg.id !== undefined) {
        // a request from the server (configuration, registrations): answer with defaults
        const items = msg.params?.items;
        this.send({ jsonrpc: "2.0", id: msg.id, result: items ? items.map(() => null) : null });
      } else if (msg.id !== undefined) {
        this.waiting.get(msg.id)?.(msg.result);
        this.waiting.delete(msg.id);
      }
    }
  }
  send(msg) {
    const body = Buffer.from(JSON.stringify(msg));
    this.proc.stdin.write(Buffer.concat([Buffer.from(`Content-Length: ${body.length}\r\n\r\n`), body]));
  }
  request(method, params) {
    const id = ++this.next;
    return new Promise((resolve) => {
      this.waiting.set(id, resolve);
      this.send({ jsonrpc: "2.0", id, method, params });
    });
  }
  notify(method, params) {
    this.send({ jsonrpc: "2.0", method, params });
  }
  async start() {
    const info = await this.request("initialize", {
      processId: process.pid,
      rootUri: uri(ROOT),
      workspaceFolders: [{ uri: uri(ROOT), name: "root" }],
      capabilities: {
        general: { positionEncodings: ["utf-16"] },
        textDocument: { typeDefinition: { linkSupport: true }, definition: { linkSupport: true } },
        workspace: { configuration: true, workspaceFolders: true },
      },
    });
    this.notify("initialized", {});
    return `${info?.serverInfo?.name ?? "tsc"} ${info?.serverInfo?.version ?? ""}`.trim();
  }
  /** Makes the server see <text> as the content of <file> (in memory only). */
  show(file, text) {
    const u = uri(file);
    const v = (this.versions.get(u) ?? 0) + 1;
    this.versions.set(u, v);
    const languageId = /\.[cm]?tsx?$/.test(file) ? (file.endsWith("x") ? "typescriptreact" : "typescript") : file.endsWith("x") ? "javascriptreact" : "javascript";
    if (v === 1) this.notify("textDocument/didOpen", { textDocument: { uri: u, languageId, version: v, text } });
    else this.notify("textDocument/didChange", { textDocument: { uri: u, version: v }, contentChanges: [{ text }] });
  }
  /** The file as it is on disk; returns its text. */
  sync(file) {
    const text = fs.readFileSync(file, "utf8");
    if (this.texts.get(file) !== text) {
      this.show(file, text);
      this.texts.set(file, text);
    }
    return text;
  }
  changed(file) {
    if (this.versions.has(uri(file))) {
      if (fs.existsSync(file)) this.sync(file);
      return;
    }
    this.notify("workspace/didChangeWatchedFiles", { changes: [{ uri: uri(file), type: fs.existsSync(file) ? 2 : 3 }] });
  }
}

// ---------------------------------------------------------------- declarations

/**
 * [package, module] of a declaration file: the npm package of the innermost
 * node_modules directory (@types/x counts as x, @types/a__b as @a/b) and the file's
 * path in it without its extension; TypeScript's own lib files (lib.*.d.ts) are
 * package "typescript"; [null, path] for the project's own files.
 */
function declaredIn(file) {
  const p = file.split(path.sep).join("/");
  const i = p.lastIndexOf("/node_modules/");
  const strip = (s) => s.replace(/(\.d)?\.[cm]?[jt]sx?$/, "");
  if (i < 0) {
    const real = fs.existsSync(file) ? fs.realpathSync(file) : file;
    return real.startsWith(ROOT + "/") ? [null, strip(real.slice(ROOT.length + 1))] : [null, null];
  }
  // TypeScript's own lib files (shipped in typescript or its native @typescript/* package)
  const lib = /\/node_modules\/(typescript|@typescript\/[^/]+)\/lib\/(lib\.[^/]*)\.d\.ts$/.exec(p);
  if (lib) return ["typescript", `typescript/lib/${lib[2]}`];
  const segs = p.slice(i + "/node_modules/".length).split("/");
  let pkg = segs[0].startsWith("@") ? `${segs[0]}/${segs[1]}` : segs[0];
  const rest = segs.slice(pkg.split("/").length).join("/");
  if (pkg.startsWith("@types/")) {
    const t = pkg.slice(7);
    pkg = t.includes("__") ? `@${t.replace("__", "/")}` : t;
  }
  return [pkg, `${pkg}/${strip(rest)}`];
}

const WORD = /[A-Za-z_$][\w$]*/y;
const KEYWORDS = new Set(["export", "declare", "default", "abstract", "class", "interface", "type", "enum", "const", "let", "var", "function", "namespace", "module"]);

function readText(file) {
  try {
    return fs.readFileSync(file, "utf8");
  } catch {
    return undefined;
  }
}

/** The declared name at <index> (keywords skipped). */
function nameAt(text, index) {
  for (let i = index; i < text.length; ) {
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      i++;
      continue;
    }
    if (!KEYWORDS.has(m[0])) return { name: m[0], end: i + m[0].length };
    i += m[0].length;
  }
  return undefined;
}

/**
 * The positions of the names a class or interface header extends or implements
 * (at depth 0 of <>, (), []; the last segment of a qualified name), from the end of
 * its name to its body.
 */
function heritage(text, from) {
  const out = [];
  let depth = 0;
  let list = false;
  for (let i = from; i < text.length; ) {
    const c = text[i];
    if (c === "/" && text[i + 1] === "/") {
      i = text.indexOf("\n", i);
      if (i < 0) break;
      continue;
    }
    if (c === "/" && text[i + 1] === "*") {
      i = text.indexOf("*/", i) + 2;
      continue;
    }
    if (c === "=" && text[i + 1] === ">") {
      i += 2;
      continue;
    }
    if ("<([{".includes(c)) {
      if (c === "{" && depth === 0) break;
      depth++;
      i++;
      continue;
    }
    if (">)]}".includes(c)) {
      depth--;
      i++;
      continue;
    }
    if ((c === ";" || c === "=") && depth === 0) break;
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      i++;
      continue;
    }
    if (depth === 0 && (m[0] === "extends" || m[0] === "implements")) list = true;
    else if (depth === 0 && list) {
      let last = i;
      let j = i + m[0].length;
      while (text[j] === "." && /[A-Za-z_$]/.test(text[j + 1] ?? "")) {
        WORD.lastIndex = j + 1;
        const n = WORD.exec(text);
        last = j + 1;
        j = j + 1 + n[0].length;
      }
      out.push(last);
      i = j;
      continue;
    }
    i += m[0].length;
  }
  return out;
}

class Types {
  constructor(server) {
    this.server = server;
    this.cache = new Map();
  }
  /** The declarations [package, module, name] of the type declared at loc and of the classes and interfaces it extends or implements, transitively. */
  async hierarchy(loc) {
    const key = `${loc.uri}:${loc.pos.line}:${loc.pos.character}`;
    if (this.cache.has(key)) return this.cache.get(key);
    const out = new Map();
    const seen = new Set();
    const todo = [loc];
    while (todo.length && seen.size < 64) {
      const l = todo.pop();
      const k = `${l.uri}:${l.pos.line}:${l.pos.character}`;
      if (seen.has(k)) continue;
      seen.add(k);
      const file = pathOf(l.uri);
      const [pkg, mod] = declaredIn(file);
      const text = readText(file);
      if (text === undefined) continue;
      const at = nameAt(text, indexOf(text, l.pos));
      if (!at) continue;
      out.set(`${pkg}\0${mod}\0${at.name}`, [pkg, mod, at.name]);
      const bases = heritage(text, at.end);
      const defs = await Promise.all(
        bases.map((b) => this.server.request("textDocument/definition", { textDocument: { uri: l.uri }, position: position(text, b) })),
      );
      // a base in a file the server has not opened: open it as it is on disk first
      for (const d of defs) for (const x of asArray(d)) todo.push(toLoc(x));
    }
    const value = [...out.values()];
    if (!pathOf(loc.uri).startsWith(ROOT + "/") || loc.uri.includes("/node_modules/")) this.cache.set(key, value);
    return value;
  }
  /**
   * wanted: [[match index, variable, start byte, end byte]]. Returns a Map
   * "index\0variable" -> declarations, from the type the server infers for each
   * expression: the file is shown to the server with each expression wrapped as
   * ({__forge_t<i>: (<expr>)}).__forge_t<i>, in memory only, and the type definition of
   * that property is asked; then the file is shown as it is.
   */
  async check(file, wanted) {
    const text = this.server.sync(file);
    const raw = Buffer.from(text, "utf8");
    const ranges = [];
    const slot = wanted.map(([, , s, e]) => {
      const r = [raw.subarray(0, s).toString("utf8").length, raw.subarray(0, e).toString("utf8").length];
      let i = ranges.findIndex(([a, b]) => a === r[0] && b === r[1]);
      if (i < 0) i = ranges.push(r) - 1;
      return i;
    });
    // inserts: at each start the opening, at each end the closing; at the same offset,
    // closings first (inner first), then openings (outer first)
    const events = [];
    ranges.forEach(([s, e], n) => {
      events.push([s, 1, -(e - s), n, `({__forge_t${n}: (`]);
      events.push([e, 0, e - s, n, `)}).__forge_t${n}`]);
    });
    events.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2] || a[3] - b[3]);
    let overlay = "";
    let last = 0;
    const anchors = [];
    for (const [off, kind, , n, piece] of events) {
      overlay += text.slice(last, off);
      last = off;
      if (kind === 0) anchors[n] = overlay.length + piece.length - 2; // inside the property name
      overlay += piece;
    }
    overlay += text.slice(last);
    this.server.show(file, overlay);
    const results = await Promise.all(
      ranges.map((_, n) => this.server.request("textDocument/typeDefinition", { textDocument: { uri: uri(file) }, position: position(overlay, anchors[n]) })),
    );
    this.server.show(file, text);
    const perRange = [];
    for (const r of results) {
      const decls = [];
      for (const l of asArray(r)) decls.push(...(await this.hierarchy(toLoc(l))));
      // any and unknown have no declaration: the checker does not know the type
      perRange.push({ decls, unknown: decls.length === 0 });
    }
    return new Map(wanted.map((w, n) => [`${w[0]}\0${w[1]}`, perRange[slot[n]]]));
  }
}

const asArray = (r) => (Array.isArray(r) ? r : r ? [r] : []);
const toLoc = (l) => ({ uri: l.targetUri ?? l.uri, pos: (l.targetSelectionRange ?? l.targetRange ?? l.range).start });

// ---------------------------------------------------------------- constraints

const listed = (v) => (v === undefined ? undefined : Array.isArray(v) ? v : [v]);

/**
 * A type spec ({package, module, name, unknown}) holds when one declaration of the type
 * (a union member, or a supertype of one) is declared there with that name; a type the
 * checker does not know (any, unknown) holds only with unknown: match.
 */
function satisfies({ decls, unknown }, spec) {
  if (unknown) return spec.unknown === "match";
  const pkgs = listed(spec.package);
  const mods = listed(spec.module);
  const names = listed(spec.name);
  return decls.some(
    ([pkg, mod, name]) =>
      (!pkgs || pkgs.includes(pkg)) && (!mods || mods.some((m) => mod === m || (mod ?? "").startsWith(`${m}/`))) && (!names || names.includes(name)),
  );
}
const holds = (decls, cond) => (cond.not ? !holds(decls, cond.not) : satisfies(decls, cond.type));

async function answer(types, matches) {
  const byFile = new Map();
  matches.forEach((m, n) => {
    const where = m.metadata?.forge_where ?? {};
    const single = m.metaVariables?.single ?? {};
    for (const v of Object.keys(where)) {
      if (!single[v]) continue;
      const b = single[v].range.byteOffset;
      if (!byFile.has(m.file)) byFile.set(m.file, []);
      byFile.get(m.file).push([n, v, b.start, b.end]);
    }
  });
  const found = new Map();
  for (const [f, wanted] of byFile) for (const [k, d] of await types.check(path.join(ROOT, f), wanted)) found.set(k, d);
  return matches.flatMap((m, n) =>
    Object.entries(m.metadata?.forge_where ?? {}).every(([v, cond]) => !found.has(`${n}\0${v}`) || holds(found.get(`${n}\0${v}`), cond)) ? [n] : [],
  );
}

// ---------------------------------------------------------------- the FIFO loop

function reply(dir, lines) {
  let fd;
  try {
    fd = fs.openSync(path.join(dir, "reply"), fs.constants.O_WRONLY | fs.constants.O_NONBLOCK);
  } catch {
    return; // nobody waits for it
  }
  const data = Buffer.from([...lines, "end"].map((l) => `${l}\n`).join(""));
  for (let off = 0; off < data.length; ) {
    try {
      off += fs.writeSync(fd, data, off);
    } catch (e) {
      if (e.code !== "EAGAIN") break;
    }
  }
  fs.closeSync(fd);
}

function cleanup() {
  for (const n of ["ready", "pid", "in"]) fs.rmSync(path.join(STATE, n), { force: true });
}

/** Tells the starter (waiting on <state>/started) how the start went. */
function started(line) {
  try {
    const fd = fs.openSync(path.join(STATE, "started"), fs.constants.O_WRONLY | fs.constants.O_NONBLOCK);
    fs.writeSync(fd, `${line}\n`);
    fs.closeSync(fd);
  } catch {
    // nobody waits for it
  }
}

async function main() {
  // detach: a session of its own, so ending the hook that started it does not end it
  if (!process.env.FORGE_TYPES_DETACHED) {
    spawn(process.execPath, process.argv.slice(1), { detached: true, stdio: "ignore", env: { ...process.env, FORGE_TYPES_DETACHED: "1" } }).unref();
    return;
  }
  fs.writeFileSync(path.join(STATE, "pid"), `${process.pid}\n`);
  const fd = fs.openSync(path.join(STATE, "in"), fs.constants.O_RDWR);
  const server = new Server();
  const ready = await server.start();
  fs.writeFileSync(path.join(STATE, "ready"), `${ready}\n`);
  log("started", ready, "for", ROOT);
  started(`ready ${ready}`);
  const types = new Types(server);
  // "stop<TAB><dir>": answered in <dir>/reply once the server has exited
  const stop = (why, dir) => {
    log("exiting:", why);
    cleanup();
    server.proc.removeAllListeners("exit");
    const done = () => {
      if (dir) reply(dir, []);
      process.exit(0);
    };
    if (server.proc.exitCode !== null || server.proc.signalCode !== null) done();
    server.proc.once("exit", done);
    setTimeout(() => server.proc.kill("SIGKILL"), 5000).unref();
    server.proc.kill();
  };
  let idle = setTimeout(() => stop("idle"), IDLE);
  // the state directory was dropped (its FIFO gone or replaced) or the repository is gone:
  // nobody can reach this daemon any more
  const inode = fs.fstatSync(fd).ino;
  setInterval(() => {
    let gone;
    try {
      gone = fs.statSync(path.join(STATE, "in")).ino !== inode || !fs.existsSync(ROOT);
    } catch {
      gone = true;
    }
    if (gone) {
      log("orphaned, exiting");
      server.proc.removeAllListeners("exit");
      server.proc.kill();
      process.exit(0);
    }
  }, 10_000).unref();
  let buf = "";
  let queue = Promise.resolve();
  const stream = fs.createReadStream(null, { fd, autoClose: false, encoding: "utf8" });
  stream.on("data", (chunk) => {
    clearTimeout(idle);
    idle = setTimeout(() => stop("idle"), IDLE);
    buf += chunk;
    for (let i; (i = buf.indexOf("\n")) >= 0; ) {
      const line = buf.slice(0, i);
      buf = buf.slice(i + 1);
      // one line at a time, in order
      queue = queue.then(() => {
        if (line.startsWith("changed\t")) server.changed(path.join(ROOT, line.slice(8)));
        else if (line === "stop" || line === "restart") stop(`asked to ${line}`);
        else if (line.startsWith("stop\t")) stop("asked to stop", line.slice(5));
        else if (line.startsWith("/")) return question(types, line);
      });
    }
  });
}

async function question(types, dir) {
  const req = readText(path.join(dir, "req"));
  if (req === undefined) return;
  const matches = [];
  const raw = [];
  const out = [];
  for (const l of req.split("\n")) {
    if (!l) continue;
    try {
      matches.push(JSON.parse(l));
      raw.push(l);
    } catch {
      out.push(`error\tunreadable match: ${l.slice(0, 80)}`);
    }
  }
  const t = performance.now();
  try {
    for (const n of await answer(types, matches)) out.push(raw[n]);
  } catch (e) {
    log("error", e.stack ?? e);
    out.push(`error\t${e.message ?? e}`);
  }
  log(`answered ${matches.length} matches in ${(performance.now() - t).toFixed(1)} ms`);
  reply(dir, out);
}

main().catch((e) => {
  log("failed", e.stack ?? e);
  started(`failed ${e.message ?? e}`);
  cleanup();
  process.exit(2);
});
